/// <summary>
/// designed from AVA
/// </summary>
public class AVASpecialDiscQuotation extends common
{
}

Method.Source:
/// <summary>
/// desigend from AVA
/// </summary>
public void setAllDiscountFactor()
{
    this.AllDiscountFactor = 1;
    this.AllDiscountFactor = (this.AllDiscountFactor - (this.SpecialDiscountPct1/100))*
                             (1 - (this.SpecialDiscountPct2/100))*
                             (1 - (this.SpecialDiscountPct3/100));
}

/// <summary>
///    designed from AVA
/// </summary>
public void initFromSalesParameters()
{
    AVASalesParameters          avaSalesParameters = AVASalesParameters::find();
    this.SpecialDiscountId1 = avaSalesParameters.QuotationSpecialDiscount1;
    this.SpecialDiscountId2 = avaSalesParameters.QuotationSpecialDiscount2;
    this.SpecialDiscountId3 = avaSalesParameters.QuotationSpecialDiscount3;
}

/// <summary>
/// designed from AVA
/// </summary>
public void update()
{
    AVASpecialDiscQuotation     specialDiscQuotOrig = this.orig();
    if (specialDiscQuotOrig.SpecialDiscountPct1 != this.SpecialDiscountPct1
    ||  specialDiscQuotOrig.SpecialDiscountPct2 != this.SpecialDiscountPct2
    ||  specialDiscQuotOrig.SpecialDiscountPct3 != this.SpecialDiscountPct3
    ||  specialDiscQuotOrig.SpecialDiscountId1  != this.SpecialDiscountId1
    ||  specialDiscQuotOrig.SpecialDiscountId2  != this.SpecialDiscountId2
    ||  specialDiscQuotOrig.SpecialDiscountId3  != this.SpecialDiscountId3)
    {

        this.setAllDiscountFactor();
        /*ttsbegin;
    SalesQuotationTable sqt = SalesQuotationTable::find(this.QuotationId,true);
    sqt.AVAPosted = false;
    sqt.AVAPostedEnum = AVAPostedEnum::NotPosted;
    sqt.doUpdate();
    ttscommit;*/
        SalesQuotationTable::AVASetQuotNotPosted(this.QuotationId);
    }
    super();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_quotationId">_quotationId</param>
/// <param name = "_update">_update</param>
/// <returns>AVASpecialDiscQuotation</returns>
public static  AVASpecialDiscQuotation find(QuotationId       _quotationId, boolean       _update = false)
{
    AVASpecialDiscQuotation         specialDiscQuotation;
    ;

    specialDiscQuotation.selectForUpdate(_update);
    select firstonly specialDiscQuotation
        where specialDiscQuotation.QuotationId == _quotationId;

    return specialDiscQuotation;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_salesQuotationTable">_salesQuotationTable</param>
public static void createFromSalesQuotationTable(SalesQuotationTable    _salesQuotationTable)
{
    AVASpecialDiscQuotation     specialDiscQuotation;
    specialDiscQuotation.QuotationId = _salesQuotationTable.QuotationId;
    specialDiscQuotation.initFromSalesParameters();
    specialDiscQuotation.setAllDiscountFactor();
    specialDiscQuotation.insert();
}

/// <summary>
/// designed by AVANADE WEN
/// </summary>
/// <param name = "_QuotationId">QuotationId</param>
/// <param name = "_fromSpecialDiscQuotation">AVASpecialDiscQuotation</param>
public static void copyFromSpecialDiscQoutation(QuotationId _QuotationId, AVASpecialDiscQuotation    _fromSpecialDiscQuotation)
{
    ttsbegin;
    AVASpecialDiscQuotation toSpecialDiscQuotation = AVASpecialDiscQuotation::find(_QuotationId, true);
    toSpecialDiscQuotation.SpecialDiscountId1   = _fromSpecialDiscQuotation.SpecialDiscountId1;
    toSpecialDiscQuotation.SpecialDiscountId2   = _fromSpecialDiscQuotation.SpecialDiscountId2;
    toSpecialDiscQuotation.SpecialDiscountId3   = _fromSpecialDiscQuotation.SpecialDiscountId3;
    toSpecialDiscQuotation.SpecialDiscountPct1  = _fromSpecialDiscQuotation.specialDiscountPct1;
    tospecialDiscQuotation.SpecialDiscountPct2  = _fromSpecialDiscQuotation.SpecialDiscountPct2;
    toSpecialDiscQuotation.SpecialDiscountPct3  = _fromSpecialDiscQuotation.SpecialDiscountPct3;
    if (toSpecialDiscQuotation)
    {
        toSpecialDiscQuotation.update();
    }
    else
    {
        toSpecialDiscQuotation.QuotationId = _QuotationId;
        toSpecialDiscQuotation.setAllDiscountFactor();
        toSpecialDiscQuotation.insert();
    }
    ttscommit;
}

/// <summary>
