    toSpecialDiscQuotation.SpecialDiscountId1   = _fromSpecialDiscQuotationJour.SpecialDiscountId1;
    toSpecialDiscQuotation.SpecialDiscountId2   = _fromSpecialDiscQuotationJour.SpecialDiscountId2;
    toSpecialDiscQuotation.SpecialDiscountId3   = _fromSpecialDiscQuotationJour.SpecialDiscountId3;
    toSpecialDiscQuotation.SpecialDiscountPct1  = _fromSpecialDiscQuotationJour.specialDiscountPct1;
    tospecialDiscQuotation.SpecialDiscountPct2  = _fromSpecialDiscQuotationJour.SpecialDiscountPct2;
    toSpecialDiscQuotation.SpecialDiscountPct3  = _fromSpecialDiscQuotationJour.SpecialDiscountPct3;
    if (toSpecialDiscQuotation)
    {
        toSpecialDiscQuotation.update();
    }
    else
    {
        toSpecialDiscQuotation.QuotationId = _QuotationId;
        toSpecialDiscQuotation.setAllDiscountFactor();
        toSpecialDiscQuotation.insert();
    }
    ttscommit;
}

/// <summary>
/// designed by AVANADE 
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    SalesQuotationLine  SalesQuotationLine;

    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(AVASpecialDiscQuotation, SpecialDiscountId1) :
        case fieldNum(AVASpecialDiscQuotation, SpecialDiscountId2) :
        case fieldNum(AVASpecialDiscQuotation, SpecialDiscountId3) :
        case fieldNum(AVASpecialDiscQuotation, SpecialDiscountPct1) :
        case fieldNum(AVASpecialDiscQuotation, SpecialDiscountPct2) :
        case fieldNum(AVASpecialDiscQuotation, SpecialDiscountPct3) :
            while select  salesQuotationLine
                where salesQuotationLine.QuotationId == this.QuotationId
            {
                salesQuotationLine.KCS_LimitPrice           = salesQuotationLine.AVAcalcLimitPrice(this);
                salesquotationLine.KCS_LimitPricePuffer     = salesquotationLine.AVAcalcLimitPricePuffer();
                salesQuotationLine.selectForUpdate(true);
                ttsbegin;
                salesQuotationLine.doUpdate();
                ttscommit;
            }
            break;

        default :
            break;
    }
}
